# Everyday words that appear in many of the 100 FAQ questions; they must not
# pick an FAQ on their own ("मेरे पास पैसे नहीं है" is not a question).
_FAQ_GENERIC_WORDS = {
    "मेरे", "पास", "दे", "दिया", "दिए", "दी", "अपने", "अपना", "अपनी", "वाला", "वाली", "वाले",
    "अच्छा", "अच्छी", "अच्छे", "प्रोडक्ट", "माल", "सामान", "सवाल", "लिए", "चाहते", "चाहता",
    "देना", "देने", "लेना", "लेने", "करवाना", "बनवाया", "दो",
}
_HINDI_FUNCTION_WORDS |= _FAQ_GENERIC_WORDS

_FAQ_INDEX = None
_FAQ_SIGNATURE = None


def _content_tokens(value):
    return tuple(
        token for token in value.split()
        if token not in _HINDI_FUNCTION_WORDS and len(token) >= 2
    )


def _get_faq_index():
    """Build once and rebuild automatically whenever the FAQ table changes."""
    global _FAQ_INDEX, _FAQ_SIGNATURE
    signature = tuple((tuple(aliases), answer) for aliases, answer in HINDI_FAQS) + tuple(
        tuple(tuple(group) for group in groups) for groups in HINDI_FAQ_KEYWORDS
    )
    if signature == _FAQ_SIGNATURE:
        return _FAQ_INDEX

    rows = []
    token_rows = {}
    for row_index, (aliases, answer) in enumerate(HINDI_FAQS):
        normalized_aliases = tuple((normalize(alias), alias) for alias in aliases)
        keyword_groups = HINDI_FAQ_KEYWORDS[row_index] if row_index < len(HINDI_FAQ_KEYWORDS) else ((), (), ())
        normalized_keywords = tuple(
            (normalize(value), value)
            for group in keyword_groups for value in group if normalize(value)
        )
        row_tokens = set()
        for normalized_alias, _ in normalized_aliases:
            row_tokens.update(_content_tokens(normalized_alias))
        for normalized_keyword, _ in normalized_keywords:
            row_tokens.update(_content_tokens(normalized_keyword))
        rows.append({"answer": answer, "aliases": normalized_aliases,
                     "keywords": normalized_keywords, "tokens": tuple(row_tokens)})
        for token in row_tokens:
            token_rows.setdefault(token, set()).add(row_index)

    row_count = max(1, len(rows))
    weights = {
        token: 1.0 + log((row_count + 1.0) / (len(indices) + 0.5))
        for token, indices in token_rows.items()
    }
    _FAQ_SIGNATURE = signature
    _FAQ_INDEX = rows, weights, token_rows
    return _FAQ_INDEX


@lru_cache(maxsize=65536)
def _word_similarity(left, right):
    score = SequenceMatcher(None, left, right).ratio()
    shorter, longer = sorted((left, right), key=len)
    if len(shorter) >= 4 and longer.startswith(shorter):
        score = max(score, 0.92)
    return score


def _keyword_prediction(question, rows, weights, token_rows):
    """Rank all FAQ rows using topic words learned from the current table."""
    query_tokens = _content_tokens(question)
    if not query_tokens:
        return None

    ranked = []
    default_weight = 1.0 + log((len(rows) + 1.0) / 1.5)
    query_weight = sum(weights.get(token, default_weight) for token in query_tokens)
    for row_index, row in enumerate(rows):
        evidence = 0.0
        matched_query_weight = 0.0
        matches = []
        for query_token in query_tokens:
            candidates = [
                (_word_similarity(query_token, token), token)
                for token in row["tokens"]
            ]
            similarity, matched_token = max(candidates, default=(0.0, ""))
            if similarity < 0.68:
                continue
            weight = weights.get(matched_token, default_weight)
            evidence += weight * similarity * similarity
            matched_query_weight += weights.get(query_token, default_weight)
            matches.append(
                (query_token, matched_token, similarity, len(token_rows.get(matched_token, ())))
            )
        coverage = min(1.0, matched_query_weight / query_weight) if query_weight else 0.0
        ranked.append((evidence * (0.55 + 0.45 * coverage), coverage, matches, row_index))

    ranked.sort(reverse=True)
    best = ranked[0]
    second_score = ranked[1][0] if len(ranked) > 1 else 0.0
    distinct_single = (
        len(best[2]) == 1
        and len(best[2][0][0]) >= 3
        and best[2][0][2] >= 0.82
        and best[2][0][3] == 1
        and best[1] >= 0.70
    )
    enough_evidence = len(best[2]) >= 2 or distinct_single
    clearly_best = best[0] >= 1.35 and best[0] - second_score >= 0.65
    if enough_evidence and clearly_best:
        row = rows[best[3]]
        details = ",".join(f"{query}->{alias}" for query, alias, _, _ in best[2])
        # The evidence and runner-up checks above have already established a
        # unique FAQ intent. Return a score that clears the runtime gate; this
        # prevents a correct one/two-keyword match from being discarded later.
        score = min(0.94, 0.84 + 0.02 * best[0])
        return row["answer"], score, f"keywords:{details}"
    return None


def _has_content_evidence(question, alias):
    """Ensure a prediction shares a real topic word, not only grammar words."""
    query_tokens = [token for token in question.split() if token not in _HINDI_FUNCTION_WORDS]
    alias_tokens = [token for token in alias.split() if token not in _HINDI_FUNCTION_WORDS]
    if not alias_tokens:
        # Aliases made only of common words ("आप क्या कर सकते हैं") have no
        # topic word to share; the caller must then say nearly the same words.
        return SequenceMatcher(None, question.replace(" ", ""), alias.replace(" ", "")).ratio() >= 0.85
    for token in query_tokens:
        for other in alias_tokens:
            similarity = _word_similarity(token, other)
            if similarity >= 0.68:
                return True
    return False


def match(question):
    normalized = normalize(question)
    if not normalized:
        return None, 0.0, None
    rows, weights, token_rows = _get_faq_index()
    for row in rows:
        for candidate, _ in row["aliases"]:
            if normalized == candidate or normalized.replace(' ', '') == candidate.replace(' ', ''):
                return row["answer"], 1.0, candidate
    padded = f" {normalized} "
    for row in rows:
        for candidate, _ in row["aliases"]:
            # Whole words only: "कैसे होगी" must not contain the alias "कैसे हो".
            if len(candidate.split()) >= 2 and f" {candidate} " in padded:
                return row["answer"], 0.96, candidate

    keyword_match = _keyword_prediction(normalized, rows, weights, token_rows)
    if keyword_match is not None:
        return keyword_match
    # Rank every alias from the FAQ table. Nothing here knows that a row is a
    # name, contact, price, etc. New or edited FAQ rows therefore participate
    # automatically without another code rule.
    if looks_hindi(question):
        ranked = []
        for row in rows:
            candidates = [
                (_similarity(normalized, candidate), alias)
                for candidate, alias in row["aliases"] if looks_hindi(alias)
            ]
            if candidates:
                similarity, alias = max(candidates)
                ranked.append((similarity, row["answer"], alias))
        ranked.sort(reverse=True)
        if ranked:
            best = ranked[0]
            second = ranked[1] if len(ranked) > 1 else (0.0, None, None)
            # Require both a strong prediction and clear separation from the
            # runner-up. Ambiguous/unrelated speech deliberately stays unknown.
            margin = best[0] - second[0]
            confident = (
                (best[0] >= 0.72 and margin >= 0.055)
                or (best[0] >= 0.62 and margin >= 0.11)
                or (best[0] >= 0.54 and margin >= 0.18)
            )
            if confident and _has_content_evidence(normalized, normalize(best[2])):
                return best[1], best[0], f"predicted:{best[2]}"
    return None, 0.0, None
